-- The bottle catalog: what each shared ingredient is, one row per bottle,
-- the bottles bars stock, and the right parents (after 20261008900000).
--
--   * every shared ingredient says what it is: 1,944 bottles, 2,352 house preps and 2,385 styles.
--   * copies of the same bottle fold into one (1,022 rows into 704):
--     "Bacardi 8", "Bacardi 8yr", "Bacardí Ocho" and "Bacardi Eight" are one
--     bottle. Different expressions never fold (Dewar's White Label and
--     Dewar's 12 stay two). Folded names stay as aliases, so typing one finds
--     the bottle. 82 kept rows take a clearer name.
--   * 509 bottles that bars stock and the list didn't have yet, so
--     each style lists the bottles you can buy (Sweet Vermouth: Carpano Antica
--     Formula, Cocchi Vermouth di Torino, Punt e Mes...), with maker, ABV and
--     origin. 12 new styles they needed.
--   * 1,335 rows get the right parent (Hamilton 86 Demerara -> Demerara
--     Rum, Bulleit -> Bourbon, rows with no parent at all), and 160 house
--     preps say which bottle they're made from ("Banana-Infused Michter's" is
--     made from Michter's and stays a kind of Bourbon).
--   * 623 bottles gain a maker or ABV they were missing.
--
-- Classified family by family from every shared ingredient name in
-- production (2026-10-08); scratch notes aren't in the repo. Matched by
-- name key, so rows that don't exist here are skipped, and a second run
-- changes nothing more. Venue ingredients aren't touched: their names are
-- private. ABVs are the standard bottling; a blank one wasn't certain.

SET "app.image_worker" = 'on';

-- No paid flavour jobs (same rule as 20261008100100): note the queue now and
-- put it back at the end. A new parent changes a few drinks' flavour rules;
-- that refill runs separately, once it's OK'd.
CREATE TEMP TABLE "flavor_jobs_before" AS SELECT * FROM "private"."item_flavor_jobs";


CREATE TEMP TABLE role_in (name text PRIMARY KEY, role text NOT NULL);

